//! The person segmentation on the GPU: the same model as the CPU's ([`super::segment`]), as Burn code generated from
//! its ONNX at build time (`build.rs`), run by Burn's wgpu backend (Vulkan; Metal on macOS; kernels fused). On a GPU a run takes a few
//! milliseconds and leaves the CPU to the call.
//!
//! - **Which GPU**: an integrated one, else a discrete one ([`KINDS`]). The model is small enough for any GPU, and
//!   a laptop's discrete GPU, woken for it, would stay awake (and drain the battery) for as long as the app runs.
//!   Never a software adapter (lavapipe, llvmpipe), which is slower than the CPU path. None, or one that can't be set
//!   up: the CPU it is.
//! - **Made ready once per process, off the camera's way**: the first time the segmentation asks ([`ready`]), a
//!   thread of its own (`teams-media-gpu`) sets the GPU up, loads the weights (built in) and runs the model once:
//!   the first run compiles its kernels, a second or more. Meanwhile, and whenever the GPU isn't there, the CPU
//!   segments, so the effect never waits for it.
//! - **Checked before it is trusted**: that first run's mask must match the CPU's for the same picture within
//!   [`AGREE`]; a driver that computes something else is left alone.
//! - **Dropped when it fails**: a run that fails or panics (a lost device) turns the GPU off for the rest of the
//!   process ([`disable`]); the CPU takes over from that frame.
//!
//! The runtimes' own configuration files (`cubecl.toml`, `burn.toml` in the working directory or above) are never
//! read: their defaults are set first, so nothing on disk changes how the app runs and nothing is cached to disk.

use std::panic::{self, AssertUnwindSafe};
use std::sync::{Arc, Mutex, MutexGuard, PoisonError};
use std::thread;

use burn::backend::wgpu::graphics::AutoGraphicsApi;
use burn::backend::wgpu::{RuntimeOptions, WgpuDevice, try_init_setup};
use burn::prelude::{Device, Tensor, TensorData};
use burn::tensor::Bytes;
use cubecl::config::{CubeClRuntimeConfig, RuntimeConfig as _};
use cubecl::wgpu::WgpuDeviceKind;

use super::segment::{MODEL_HEIGHT, MODEL_PIXELS, MODEL_WIDTH, Segment};

/// The model as Burn code, generated by `build.rs` from the ONNX: a module of burn-onnx's, with its lints.
#[expect(
    clippy::allow_attributes,
    clippy::allow_attributes_without_reason,
    clippy::default_trait_access,
    clippy::panic,
    clippy::similar_names,
    clippy::too_many_lines,
    clippy::unreadable_literal,
    reason = "generated by burn-onnx at build time, never edited"
)]
mod model {
    include!(concat!(env!("OUT_DIR"), "/model/selfie_segmenter_landscape.rs"));
}

/// The model's weights, as burn-onnx wrote them beside its code.
const WEIGHTS: &[u8] = include_bytes!(concat!(env!("OUT_DIR"), "/model/selfie_segmenter_landscape.bpk"));

/// The adapters tried, in order: the first integrated GPU, then the first discrete one.
#[cfg(not(test))]
const KINDS: &[WgpuDeviceKind] = &[WgpuDeviceKind::IntegratedGpu(0), WgpuDeviceKind::DiscreteGpu(0)];
/// ... and in this crate's tests a software adapter last: the only one CI has, so the GPU path runs there too.
#[cfg(test)]
const KINDS: &[WgpuDeviceKind] = &[
    WgpuDeviceKind::IntegratedGpu(0),
    WgpuDeviceKind::DiscreteGpu(0),
    WgpuDeviceKind::Cpu,
];

/// How far the GPU's first mask may be from the CPU's, per pixel (a confidence in `[0, 1]`).
const AGREE: f32 = 0.01;

/// The GPU's model, set up and checked.
pub(super) struct Gpu {
    model: Mutex<model::Model>,
    device: Device,
    /// The adapter's name, as its driver gives it.
    name: String,
}

impl std::fmt::Debug for Gpu {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("Gpu").field("name", &self.name).finish_non_exhaustive()
    }
}

impl Segment for Gpu {
    fn segment(&self, input: &[f32]) -> Result<Vec<f32>, String> {
        let model = self.model.lock().unwrap_or_else(PoisonError::into_inner);
        let confidence = caught(|| {
            let shape = [1, 3, MODEL_HEIGHT, MODEL_WIDTH];
            let input = Tensor::<4>::from_data(TensorData::new(input.to_vec(), shape), &self.device);
            model.forward(input).into_data().try_to_vec::<f32>()
        })?
        .map_err(|error| format!("{error:?}"))?;
        if confidence.len() != MODEL_PIXELS {
            return Err(format!("the model gave {} values", confidence.len()));
        }
        Ok(confidence)
    }
}

/// Where the process's GPU stands.
enum State {
    /// Nobody asked yet.
    Idle,
    /// Being set up on its thread.
    Preparing,
    Ready(Arc<Gpu>),
    /// None, or it failed: the CPU segments.
    Off,
}

static STATE: Mutex<State> = Mutex::new(State::Idle);

fn state() -> MutexGuard<'static, State> {
    STATE.lock().unwrap_or_else(PoisonError::into_inner)
}

/// The GPU's model once it is ready; `None` while it is being made ready (the first call starts that) and when there
/// is none.
pub(super) fn ready() -> Option<Arc<Gpu>> {
    let mut state = state();
    match &*state {
        State::Ready(gpu) => Some(Arc::clone(gpu)),
        State::Preparing | State::Off => None,
        State::Idle => {
            let started = thread::Builder::new()
                .name("teams-media-gpu".into())
                .spawn(|| settle(prepare(KINDS)));
            *state = match started {
                Ok(_) => State::Preparing,
                Err(error) => {
                    log::info!("the person segmentation runs on the CPU: no thread for the GPU: {error}");
                    State::Off
                }
            };
            None
        }
    }
}

/// Turns the GPU off for the rest of the process: it failed with `error`.
pub(super) fn disable(error: &str) {
    log::warn!("the person segmentation's GPU failed, it runs on the CPU from now: {error}");
    *state() = State::Off;
}

/// Whether the GPU is still being made ready (tests wait for it to settle).
#[cfg(test)]
pub(super) fn preparing() -> bool {
    matches!(*state(), State::Idle | State::Preparing)
}

/// Keeps what [`prepare`] made of the GPU.
fn settle(prepared: Result<Gpu, String>) {
    let next = match prepared {
        Ok(gpu) => {
            log::info!("the person segmentation runs on the GPU ({})", gpu.name);
            State::Ready(Arc::new(gpu))
        }
        Err(error) => {
            log::info!("the person segmentation runs on the CPU: {error}");
            State::Off
        }
    };
    *state() = next;
}

/// The model set up on the first adapter of `kinds` there is, loaded, run once and checked against the CPU's mask.
pub(super) fn prepare(kinds: &[WgpuDeviceKind]) -> Result<Gpu, String> {
    // the defaults, before anything reads them: no configuration file from the working directory
    let _ = CubeClRuntimeConfig::try_set(CubeClRuntimeConfig::default());
    let _ = burn::BurnConfig::try_set(burn::BurnConfig::default());
    let (device, name) = adapter(kinds)?;
    let model = caught(|| model::Model::from_bytes(Bytes::from_bytes_vec(WEIGHTS.to_vec()), &device))?;
    let gpu = Gpu {
        model: Mutex::new(model),
        device,
        name,
    };
    let input = sample_input();
    let gpu_mask = gpu.segment(&input)?;
    let cpu_mask = super::segment::plan().and_then(|plan| plan.segment(&input))?;
    let apart = farthest(&gpu_mask, &cpu_mask);
    if apart > AGREE {
        return Err(format!("{}'s mask is {apart} from the CPU's", gpu.name));
    }
    Ok(gpu)
}

/// The first adapter of `kinds` that sets up, as Burn's device, and its name.
fn adapter(kinds: &[WgpuDeviceKind]) -> Result<(Device, String), String> {
    let options = || RuntimeOptions::try_default().map_err(|error| error.to_string());
    let mut failures = Vec::new();
    for kind in kinds {
        let device = WgpuDevice::new(kind.clone());
        let setup = options().and_then(|options| {
            caught(|| try_init_setup::<AutoGraphicsApi>(&device, options))?.map_err(|error| error.to_string())
        });
        match setup {
            Ok(setup) => return Ok((Device::from(device), setup.adapter.get_info().name)),
            Err(error) => failures.push(format!("{kind:?}: {error}")),
        }
    }
    Err(format!("no GPU ({})", failures.join("; ")))
}

/// A picture to run the model on once: a fixed pattern of the model's input size.
fn sample_input() -> Vec<f32> {
    (0..3 * MODEL_PIXELS)
        .map(|index| f32::from(u8::try_from(index * 37 % 251).unwrap_or(0)) / 250.0)
        .collect()
}

/// The largest difference between two masks of the same size; infinite when their sizes differ.
pub(super) fn farthest(one: &[f32], other: &[f32]) -> f32 {
    if one.len() != other.len() {
        return f32::INFINITY;
    }
    one.iter()
        .zip(other)
        .map(|(one, other)| (one - other).abs())
        .fold(0.0, f32::max)
}

/// `work`'s result, or what it panicked with: the GPU runtime panics where it can't go on (a lost device).
pub(super) fn caught<T>(work: impl FnOnce() -> T) -> Result<T, String> {
    panic::catch_unwind(AssertUnwindSafe(work)).map_err(|payload| {
        payload
            .downcast_ref::<String>()
            .cloned()
            .or_else(|| payload.downcast_ref::<&str>().map(|message| (*message).to_owned()))
            .unwrap_or_else(|| "it panicked".to_owned())
    })
}
